/**
 * Extracts clean S3 object key from a raw DB field value.
 * Handles clean keys, /api/media/stream-url?key=... URLs, and filters out legacy HLS stream URLs.
 */
function extractCleanS3Key(val?: string | null): string | null {
  if (!val || typeof val !== 'string') return null;
  const trimmed = val.trim();
  if (!trimmed) return null;

  if (isLocalMasqueradingMedia(trimmed)) return null;

  // If it's a legacy or external stream URL that isn't S3, ignore it
  if (trimmed.includes('stream.crayonsloop.com') || trimmed.includes('test-streams.mux.dev')) {
    return null;
  }

  // If it's an API stream-url link, extract key query param
  if (trimmed.includes('/api/media/stream-url')) {
    try {
      const parsed = new URL(trimmed, 'https://crayonsloop.com');
      const paramKey = parsed.searchParams.get('key');
      if (paramKey) return paramKey.startsWith('/') ? paramKey.slice(1) : paramKey;
    } catch {
      // ignore
    }
  }

  // If it's a direct S3 key or path
  if (trimmed.startsWith('films/')) {
    return trimmed;
  }
  if (trimmed.startsWith('/films/')) {
    return trimmed.slice(1);
  }

  // If not HTTP/HTTPS, treat as relative S3 key
  if (!trimmed.startsWith('http://') && !trimmed.startsWith('https://') && !trimmed.startsWith('/')) {
    return trimmed;
  }

  return null;
}

export default async function handler(req: any, res: any) {
  if (req.method !== 'GET' && req.method !== 'POST' && req.method !== 'HEAD') {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  try {
    const params = req.method === 'POST' ? req.body : req.query;
    const { key, titleId, mediaType, redirect, token: queryToken, action } = params || {};

    if (action === 'token' || req.url?.includes('/api/media/token')) {
      const ttl = 120;
      const exp = Math.floor(Date.now() / 1000) + ttl;
      return res.status(200).json({ ok: true, exp, ttl });
    }

    if (action === 'hls' || req.url?.includes('/api/media/hls')) {
      const targetTitle = (titleId || '').trim();
      if (!targetTitle) return res.status(400).json({ error: 'Missing titleId' });
      const local = path.join(process.cwd(), 'public', 'hls', targetTitle, 'master.m3u8');
      if (fs.existsSync(local)) {
        return res.redirect(307, `/hls/${encodeURIComponent(targetTitle)}/master.m3u8`);
      }
      const HLS = process.env.LOOP_HLS_ORIGIN;
      if (!HLS || HLS.includes('stream.crayonsloop.com')) {
        return res.status(404).json({ error: 'No HLS ladder' });
      }
      const master = `${HLS.replace(/\/$/, '')}/${encodeURIComponent(targetTitle)}/master.m3u8`;
      try {
        const probe = await fetch(master, { method: 'HEAD' });
        if (!probe.ok) return res.status(404).json({ error: 'No HLS ladder' });
        return res.redirect(307, master);
      } catch {
        return res.status(404).json({ error: 'No HLS ladder' });
      }
    }

    const bucket = awsMediaBucket();
    const region = awsMediaRegion();
    const accessKey = process.env.AWS_ACCESS_KEY_ID;
    const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

    if (!accessKey || !secretKey) {
      return res.status(500).json({ error: 'AWS media configuration not set on server' });
    }

    let targetKey = key;
    let resolvedTitleId = titleId ? String(titleId).toLowerCase().trim() : '';
    let dbTitleRecord: any = null;

    const supabaseUrl = process.env.VITE_SUPABASE_URL || 
                        process.env.NEXT_PUBLIC_SUPABASE_URL || 
                        process.env.SUPABASE_URL ||
                        'https://uakpqqardziifcwzvgfx.supabase.co';
    const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || 
                        process.env.VITE_SUPABASE_ANON_KEY || 
                        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

    // 1. Authoritative Database Source-of-Truth Resolution
    if (resolvedTitleId && supabaseKey) {
      try {
        const supabase = createClient(supabaseUrl, supabaseKey);
        const { data: dbData } = await supabase
          .from('loop_titles')
          .select('*')
          .or(`id.eq.${resolvedTitleId},slug.eq.${resolvedTitleId}`)
          .maybeSingle();

        if (dbData) {
          dbTitleRecord = dbData;
          if (!targetKey) {
            if (mediaType === 'trailer') {
              targetKey = extractCleanS3Key(dbData.trailer_path) || extractCleanS3Key(dbData.trailer_stream_url);
            } else if (mediaType === 'poster') {
              targetKey = extractCleanS3Key(dbData.poster_path) || extractCleanS3Key(dbData.backdrop_path);
            } else {
              targetKey = extractCleanS3Key(dbData.playback_path) || extractCleanS3Key(dbData.stream_playback_url);
            }
          }
        }
      } catch (dbErr) {
        console.warn('[stream-url] Authoritative DB lookup warning:', dbErr);
      }
    }

    // 2. Fallback to KNOWN_FILMS_MEDIA dictionary (backward-compatibility during migration)
    if (!targetKey && resolvedTitleId) {
      const mediaEntry = KNOWN_FILMS_MEDIA[resolvedTitleId];
      if (mediaEntry) {
        if (mediaType === 'trailer') {
          targetKey = mediaEntry.trailer;
        } else if (mediaType === 'poster') {
          targetKey = mediaEntry.poster;
        } else {
          targetKey = mediaEntry.video;
        }
      }
    }

    // 3. Deterministic rejection if neither key nor known titleId can be resolved
    if (!targetKey) {
      return res.status(400).json({ error: 'Missing media key or unknown titleId' });
    }

    const cleanKey = targetKey.startsWith('/') ? targetKey.slice(1) : targetKey;

    if (isLocalMasqueradingMedia(targetKey) || isLocalMasqueradingMedia('/' + cleanKey)) {
      return res.status(400).json({
        error: 'Local sandbox media is not a production playback source.',
        code: 'LOCAL_MEDIA_REJECTED',
      });
    }

    // Classification: Public Asset vs Protected Asset
    const isPublicAsset = 
      mediaType === 'poster' || 
      mediaType === 'trailer' || 
      cleanKey.startsWith('films/posters/') || 
      cleanKey.startsWith('films/trailers/') ||
      cleanKey.endsWith('.jpg') || 
      cleanKey.endsWith('.jpeg') || 
      cleanKey.endsWith('.png') || 
      cleanKey.endsWith('.webp');

    // If public marketing asset, deliver without gating (24-hour signed URL)
    if (isPublicAsset) {
      const signedUrl = signS3Url(bucket, region, cleanKey, accessKey, secretKey, 86400);
      if (redirect === 'true' || redirect === '1') {
        res.setHeader('Location', signedUrl);
        return res.status(307).end();
      }
      return res.status(200).json({
        success: true,
        mediaKey: cleanKey,
        streamUrl: signedUrl,
        bucket,
        expiresInSeconds: 86400
      });
    }

    // =========================================================================
    // PROTECTED ASSET: Full movie video streaming entitlement check
    // =========================================================================

    // Reverse lookup title info if not directly supplied
    if (!resolvedTitleId) {
      for (const [tid, entry] of Object.entries(KNOWN_FILMS_MEDIA)) {
        if (entry.video && (cleanKey === entry.video || cleanKey.includes(entry.video))) {
          resolvedTitleId = tid;
          break;
        }
      }
    }

    const knownEntry = resolvedTitleId ? KNOWN_FILMS_MEDIA[resolvedTitleId] : null;
    const accessTier = dbTitleRecord?.access_tier || 
                       dbTitleRecord?.metadata?.access_tier || 
                       knownEntry?.accessTier || 
                       'SVOD';
    const isFreeTitle = accessTier === 'FREE';

    // Explicitly FREE titles can be watched by anyone (4-hour signed URL)
    if (isFreeTitle) {
      const signedUrl = signS3Url(bucket, region, cleanKey, accessKey, secretKey, 14400);
      if (redirect === 'true' || redirect === '1') {
        res.setHeader('Location', signedUrl);
        return res.status(307).end();
      }
      return res.status(200).json({
        success: true,
        mediaKey: cleanKey,
        streamUrl: signedUrl,
        bucket,
        expiresInSeconds: 14400
      });
    }

    // For SVOD / TVOD protected films, verify caller authentication & entitlement
    const authHeader = req.headers?.authorization;
    const token = (authHeader && authHeader.startsWith('Bearer ')) 
      ? authHeader.substring(7) 
      : (queryToken ? String(queryToken).trim() : null);

    if (!token) {
      return res.status(401).json({
        error: 'Unauthorized: Streaming full cinema requires an authenticated session.',
        code: 'AUTH_REQUIRED'
      });
    }

    if (!supabaseKey) {
      return res.status(503).json({
        error: 'Playback identity service is not configured.',
        code: 'SUPABASE_CONFIG_MISSING'
      });
    }

    const supabase = createClient(supabaseUrl, supabaseKey);
    const { data: userData, error: userError } = await supabase.auth.getUser(token);

    if (userError || !userData?.user) {
      return res.status(401).json({
        error: 'Unauthorized: Session token is invalid or expired.',
        code: 'INVALID_SESSION'
      });
    }

    const user = userData.user;
    // 1. Admin / Founder Bypass
    const isAdmin = await isAuthorizedStudioAdmin(user);

    if (isAdmin) {
      const signedUrl = signS3Url(bucket, region, cleanKey, accessKey, secretKey, 14400);
      if (redirect === 'true' || redirect === '1') {
        res.setHeader('Location', signedUrl);
        return res.status(307).end();
      }
      return res.status(200).json({
        success: true,
        mediaKey: cleanKey,
        streamUrl: signedUrl,
        authorizedAs: 'admin',
        expiresInSeconds: 14400
      });
    }

    // 2. SVOD Active Subscription Check
    let hasAccess = false;
    let accessGrantedType = 'NONE';

    const serviceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
    const dbClient = serviceRoleKey 
      ? createClient(supabaseUrl, serviceRoleKey)
      : createClient(supabaseUrl, supabaseKey, {
          global: {
            headers: {
              Authorization: `Bearer ${token}`
            }
          }
        });

    try {
      const { data: subData } = await dbClient
        .from('loop_subscriptions')
        .select('status, current_period_end')
        .eq('user_id', user.id)
        .eq('status', 'active')
        .maybeSingle();

      if (subData) {
        const isCurrent = !subData.current_period_end || new Date(subData.current_period_end).getTime() > Date.now();
        if (isCurrent) {
          hasAccess = true;
          accessGrantedType = 'SVOD';
        }
      }
    } catch (subErr) {
      console.warn('Subscription check error:', subErr);
    }

    // 3. TVOD Rental / Purchase Check
    if (!hasAccess && resolvedTitleId) {
      try {
        const canonicalTitleId = dbTitleRecord?.id || (resolvedTitleId === 'jananam-1947-pranayam-thudarunnu' ? '224b7245-2a08-4206-a7fd-a3dea8430eba' : resolvedTitleId);
        const { data: tvodData } = await dbClient
          .from('loop_user_tvod_entitlements')
          .select('access_type, expires_at, status')
          .eq('user_id', user.id)
          .or(`title_id.eq.${canonicalTitleId},title_id.eq.${resolvedTitleId}`)
          .eq('status', 'ACTIVE');

        if (tvodData && tvodData.length > 0) {
          for (const ent of tvodData) {
            if (ent.access_type === 'PURCHASE') {
              hasAccess = true;
              accessGrantedType = 'PURCHASE';
              break;
            }
            if (ent.access_type === 'RENTAL') {
              if (!ent.expires_at || new Date(ent.expires_at).getTime() > Date.now()) {
                hasAccess = true;
                accessGrantedType = 'RENTAL';
                break;
              }
            }
          }
        }
      } catch (tvodErr) {
        console.warn('TVOD check error:', tvodErr);
      }
    }

    if (!hasAccess) {
      return res.status(403).json({
        error: 'Entitlement required: An active subscription or valid rental is required to stream this film.',
        code: 'ENTITLEMENT_REQUIRED',
        titleId: resolvedTitleId,
      });
    }

    // Authorized playback delivery with 4-hour expiring ticket
    const signedUrl = signS3Url(bucket, region, cleanKey, accessKey, secretKey, 14400);
    if (redirect === 'true' || redirect === '1') {
      res.setHeader('Location', signedUrl);
      return res.status(307).end();
    }

    return res.status(200).json({
      success: true,
      mediaKey: cleanKey,
      streamUrl: signedUrl,
      accessType: accessGrantedType,
      expiresInSeconds: 14400
    });
  } catch (err: any) {
    console.error('Error generating signed stream URL:', err);
    return res.status(500).json({ error: err.message || 'Failed to generate stream URL' });
  }
}
